(()=>{'use strict';
const {$,$$,esc:E}=Q,langs=['en','bn','ja'];
const labels={
en:{full:'Complete surahs',intro:'Begin with a few verses. Read their meaning, listen, and return at your own pace.',guide:'A gentle introduction',source:'Read the source',note:'Source-based reading guide; a paraphrase, not a quotation or an independent tafsir.',practice:'Recitation practice and evidence',meaning:'Translation and explanation are available verse by verse below.',general:'General encouragement',benefit:'The Qur’an will intercede for its companions on the Day of Resurrection. This is encouragement for the Qur’an as a whole, not a promise tied to this particular excerpt.',noTime:'No specific time or guaranteed worldly outcome is assigned to this passage here. A personal reading routine is different from an established prophetic instruction.',yasin:'No authenticated evidence is supplied here for prescribing Ya-Sin specifically after Fajr. Read it for reflection without treating that timing as a guaranteed Sunnah benefit.',waqiah:'No authenticated evidence is supplied here for prescribing Al-Waqi‘ah after Maghrib or guaranteeing wealth. This library does not promote that claim.',sajdah:'The Prophet recited As-Sajdah and Al-Insan in the Friday Fajr prayer. This report concerns recitation within that prayer, not a rule to read it after every Fajr.',mulk:'A report graded Hasan describes the thirty-verse Surah Al-Mulk interceding until a person is forgiven. That report itself does not specify a time of day.',newFiles:'Your permitted recording',filesHelp:'Choose an MP4 or audio file you have permission to use. It stays on this device; it is not uploaded or shared publicly. Use an MP4 with H.264/AAC for broad compatibility.',choose:'Choose video / audio',restore:'Open saved recording',save:'Save recording on this device',video:'Video',audio:'Audio only',nativePip:'System Picture in Picture',float:'Move player',close:'Stop and close',seek:'Playback position',volume:'Volume',unsupported:'This browser did not allow system PiP. Try the video’s own PiP control in Safari. Home Screen apps and in-app browsers may differ.',loadFirst:'Load and start a supported video first.',saved:'Saved locally. Keep website data to retain it.',failed:'Could not load or save this file.',onlyDevice:'On iPhone, use the device volume buttons when web volume control is unavailable.',localAudio:'Audio-only playback uses your supplied media file; it does not export a separate MP3.',return:'Return to the passage',rights:'Only use recordings you are permitted to use.',original:'Original source meaning'},
bn:{full:'সম্পূর্ণ সূরা',intro:'কয়েকটি আয়াত দিয়ে শুরু করুন। অর্থ পড়ুন, শুনুন এবং নিজের গতিতে ফিরে আসুন।',guide:'সহজ পরিচয়',source:'মূল উৎস পড়ুন',note:'উৎসভিত্তিক সংক্ষিপ্ত পরিচয়; এটি সরাসরি উদ্ধৃতি বা স্বতন্ত্র তাফসির নয়।',practice:'তিলাওয়াতের আমল ও প্রমাণ',meaning:'নিচে প্রতিটি আয়াতের অনুবাদ ও ব্যাখ্যা রয়েছে।',general:'সাধারণ উৎসাহ',benefit:'কুরআন কিয়ামতের দিন তার সঙ্গীদের জন্য সুপারিশ করবে। এটি পুরো কুরআন সম্পর্কে উৎসাহ, শুধু এই অংশের জন্য আলাদা প্রতিশ্রুতি নয়।',noTime:'এখানে এই অংশের জন্য নির্দিষ্ট সময় বা নিশ্চিত পার্থিব ফল নির্ধারণ করা হয়নি। ব্যক্তিগত পাঠের রুটিন ও প্রমাণিত নববী নির্দেশ এক নয়।',yasin:'ইয়াসীন বিশেষভাবে ফজরের পরে পড়ার জন্য এখানে সহিহ প্রমাণ দেওয়া হয়নি। নির্দিষ্ট সময়কে নিশ্চিত সুন্নাহর ফজিলত না ভেবে অর্থ বোঝার জন্য পড়ুন।',waqiah:'ওয়াকিয়াহ মাগরিবের পরে পড়লে সম্পদ নিশ্চিত হবে—এমন দাবির সহিহ প্রমাণ এখানে দেওয়া হয়নি। এই লাইব্রেরি সেই দাবি প্রচার করে না।',sajdah:'নবী শুক্রবারের ফজর নামাজে আস-সাজদাহ ও আল-ইনসান পড়তেন। বর্ণনাটি নামাজের ভেতরের পাঠ সম্পর্কে, প্রতিদিন ফজরের পরে পড়ার নিয়ম নয়।',mulk:'হাসান হিসেবে মূল্যায়িত একটি বর্ণনায় ত্রিশ আয়াতের সূরা আল-মুলক ক্ষমা না হওয়া পর্যন্ত সুপারিশ করার কথা এসেছে। ওই বর্ণনা নিজে দিনের কোনো সময় নির্দিষ্ট করে না।',newFiles:'আপনার অনুমোদিত রেকর্ডিং',filesHelp:'আপনার ব্যবহার করার অনুমতি আছে এমন MP4 বা অডিও বেছে নিন। এটি এই ডিভাইসেই থাকবে; সবার জন্য আপলোড হবে না। H.264/AAC MP4 বেশিরভাগ ডিভাইসে চলে।',choose:'ভিডিও / অডিও বেছে নিন',restore:'সংরক্ষিত রেকর্ডিং খুলুন',save:'এই ডিভাইসে রেকর্ডিং রাখুন',video:'ভিডিও',audio:'শুধু অডিও',nativePip:'সিস্টেম পিকচার-ইন-পিকচার',float:'প্লেয়ার সরান',close:'থামিয়ে বন্ধ করুন',seek:'চলার সময়',volume:'ভলিউম',unsupported:'ব্রাউজার সিস্টেম PiP চালু করেনি। Safari-তে ভিডিওর নিজস্ব PiP বোতাম চেষ্টা করুন। হোম স্ক্রিন ও অন্য অ্যাপের ব্রাউজারে আচরণ ভিন্ন হতে পারে।',loadFirst:'আগে উপযুক্ত ভিডিও লোড করে চালান।',saved:'এই ডিভাইসে রাখা হয়েছে। রাখতে চাইলে ওয়েবসাইটের ডেটা মুছবেন না।',failed:'ফাইল লোড বা সংরক্ষণ হয়নি।',onlyDevice:'ওয়েব ভলিউম কাজ না করলে iPhone-এর নিজস্ব ভলিউম বোতাম ব্যবহার করুন।',localAudio:'শুধু অডিও আপনার দেওয়া ফাইল থেকেই চলে; আলাদা MP3 তৈরি করে না।',return:'পাঠের অংশে ফিরুন',rights:'শুধু অনুমোদিত রেকর্ডিং ব্যবহার করুন।',original:'মূল উৎসের অর্থ'},
ja:{full:'章全体を読む',intro:'まず数節から。意味を読み、朗誦を聴き、自分のペースで戻ってきてください。',guide:'やさしい導入',source:'出典を読む',note:'出典に基づく短い案内です。直接の引用や独立したタフスィールではありません。',practice:'朗誦の習慣と根拠',meaning:'下に各節の翻訳と解説があります。',general:'学ぶ人への励まし',benefit:'クルアーンは復活の日に、その仲間のために執り成します。これはクルアーン全体への励ましであり、この抜粋だけの特別な約束ではありません。',noTime:'この箇所に特定の時間や確実な現世の利益を割り当てていません。個人の読書習慣と、根拠のある預言者の指示は別です。',yasin:'ヤー・スィーンをファジュル後に限定する真正な根拠は、ここでは提示していません。その時間に特別な保証があるとはせず、意味を考えて読んでください。',waqiah:'アル・ワーキアをマグリブ後に読めば富が保証される、という真正な根拠はここでは提示していません。この主張を勧めるものではありません。',sajdah:'預言者は金曜日のファジュル礼拝の中で、アッサジダとアル・インサーンを朗誦されました。毎日のファジュル後に読むという規則ではありません。',mulk:'ハサンと評価された伝承では、三十節のアル・ムルクが赦されるまで執り成すと述べられます。この伝承自体は一日の時刻を指定しません。',newFiles:'使用許可のある録音',filesHelp:'使用許可のあるMP4または音声ファイルを選んでください。この端末内に保管し、公開アップロードはしません。H.264/AACのMP4は幅広い機器で再生できます。',choose:'動画・音声を選ぶ',restore:'保存した録音を開く',save:'この端末に保存',video:'動画',audio:'音声のみ',nativePip:'システムのピクチャ・イン・ピクチャ',float:'プレーヤーを移動',close:'停止して閉じる',seek:'再生位置',volume:'音量',unsupported:'ブラウザがシステムPiPを許可しませんでした。Safariの動画内PiPボタンを試してください。ホーム画面アプリやアプリ内ブラウザでは異なる場合があります。',loadFirst:'対応する動画を読み込み、再生してください。',saved:'端末内に保存しました。ウェブサイトのデータを消すと削除されます。',failed:'ファイルを読み込み、または保存できませんでした。',onlyDevice:'ウェブの音量調整が使えない場合は、iPhone本体の音量ボタンを使ってください。',localAudio:'音声のみの再生は提供されたファイルを使います。別のMP3を書き出すものではありません。',return:'読んでいた箇所へ',rights:'使用許可のある録音のみ使用してください。',original:'出典の意味'}
};
const tr=k=>labels[Q.lang]?.[k]||labels.en[k],ed={en:'english_rwwad',bn:'bengali_zakaria',ja:'japanese_saeedsato'};
for(const [rank,surahNo,surah,arabicName,total,pages]of window.FQ_FULL_SURAH_DATA){if(window.PASSAGES.some(p=>p.rank===rank))continue;window.PASSAGES.push({rank,surahNo,surah,arabicName,range:'1–'+total,open:'سورة '+arabicName,peak:'',peakAt:'Complete surah',reciters:['Mishary Rashid Alafasy','Abdul Rahman Al-Sudais','Abdul Rahman Al-Ossi','Yasser Al-Dosari'],tags:['complete surah'],why:window.FQ_GUIDES[rank].en,signal:'Complete surah',evidence:'',read:pages.map(p=>'https://www.equraninstitute.com/quranreading/'+p),listen:'https://www.youtube.com/results?search_query='+encodeURIComponent(surah+' Mishary Alafasy recitation'),fullSurah:true});}
const section=document.createElement('section');section.className='wrap library-section';section.id='completeSurahs';section.innerHTML='<h2 id="completeTitle"></h2><p id="completeIntro"></p><div id="completeGrid" class="passage-grid"></div>';$('#library').after(section);$('#completeGrid').onclick=$('#grid').onclick;
const baseRender=Q.render;Q.render=()=>{baseRender();$('#completeTitle').textContent=tr('full');$('#completeIntro').textContent=tr('intro');$('#completeGrid').replaceChildren();$$('#grid .card').forEach(card=>{const rank=+card.querySelector('[data-open]')?.dataset.open;if(rank>30)$('#completeGrid').append(card);});};
function guide(p){const source='https://quranenc.com/'+Q.lang+'/browse/'+ed[Q.lang]+'/'+p.surahNo;let text=tr('noTime'),reference='';if(p.surahNo===36)text=tr('yasin');if(p.surahNo===56)text=tr('waqiah');if(p.surahNo===32){text=tr('sajdah');reference='<a target="_blank" rel="noopener" href="https://sunnah.com/bukhari:891">Sahih al-Bukhari 891 · Sahih</a>';}if(p.surahNo===67){text=tr('mulk');reference='<a target="_blank" rel="noopener" href="https://sunnah.com/tirmidhi:2891">Jami at-Tirmidhi 2891 · Hasan (Darussalam)</a>';}
return `<article class="reading-guide" lang="${Q.lang}"><h3>${E(tr('guide'))}</h3><p>${E(window.FQ_GUIDES[p.rank]?.[Q.lang]||'')}</p><a href="${E(source)}" target="_blank" rel="noopener">${E(tr('source'))} · ${p.surahNo}:${E(p.range)} · QuranEnc</a><small>${E(tr('note'))}</small><details><summary>${E(tr('practice'))}</summary><p>${E(text)}</p>${reference}<h4>${E(tr('general'))}</h4><p>${E(tr('benefit'))}</p><a href="https://sunnah.com/muslim:804a" target="_blank" rel="noopener">Sahih Muslim 804a · Sahih</a></details><p class="source-label">${E(tr('meaning'))}</p></article>`;}
function renderGuide(){const p=Q.active;if(!p)return;$('#summary').innerHTML=guide(p);$('#v3Previous').disabled=p.rank<=1;$('#v3Next').disabled=p.rank>=window.PASSAGES.length;}
const baseOpen=Q.open;Q.open=async(rank,tab='ayahs')=>{const pending=baseOpen(rank,tab);renderGuide();await pending;if(Q.active?.rank===+rank)renderGuide();};
$('#v3Next').onclick=()=>Q.open(Math.min(window.PASSAGES.length,Q.active.rank+1));$('#v3Previous').onclick=()=>Q.open(Math.max(1,Q.active.rank-1));
// Dialogs remain within the document, so stable media nodes are not made inert or re-created.
for(const d of [$('#studyDialog'),$('#utilityDialog')]){d.showModal=function(){if(!this.open)this.show();};d.classList.add('community-dialog');}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const d=$('#utilityDialog').open?$('#utilityDialog'):$('#studyDialog');if(d.open)d.close();}});
const dock=document.createElement('section');dock.id='nativeMediaDock';dock.hidden=true;dock.className='native-media-dock';dock.innerHTML='<header id="nativeDrag"><strong id="nativeTitle"></strong><button type="button" id="nativeClose">×</button></header><video id="nativeVideo" controls playsinline webkit-playsinline preload="metadata"></video><audio id="nativeAudio" controls preload="metadata" hidden></audio><div class="control-row"><button class="btn" id="nativeVideoMode"></button><button class="btn" id="nativeAudioMode"></button><button class="btn" id="nativePip"></button><button class="btn" id="nativeSave"></button><button class="btn" id="nativeReturn"></button></div><p id="nativeStatus" role="status"></p>';document.body.append(dock);
const video=$('#nativeVideo'),audio=$('#nativeAudio');video.setAttribute('data-persistent-native','');audio.setAttribute('data-persistent-native','');let record=null,objectURL=null,owner=null,activeMedia=video;
function nativeLabels(){for(const[id,key]of[['nativeVideoMode','video'],['nativeAudioMode','audio'],['nativePip','nativePip'],['nativeSave','save'],['nativeReturn','return']])$('#'+id).textContent=tr(key);$('#nativeClose').setAttribute('aria-label',tr('close'));$('#nativeDrag').setAttribute('aria-label',tr('float'));}
function setStatus(s){$('#nativeStatus').textContent=s;}
function stopOwn(){video.pause();audio.pause();video.removeAttribute('src');audio.removeAttribute('src');video.load();audio.load();if(objectURL)URL.revokeObjectURL(objectURL);objectURL=null;record=null;dock.hidden=true;}
function mediaMetadata(el){if(!('mediaSession'in navigator)||!record)return;try{navigator.mediaSession.metadata=new MediaMetadata({title:record.label,artist:'Famous Quran · supplied recording'});for(const[a,f]of[['play',()=>el.play().catch(()=>{})],['pause',()=>el.pause()],['seekto',d=>{if(Number.isFinite(d.seekTime))el.currentTime=d.seekTime;}],['seekbackward',d=>{el.currentTime=Math.max(0,el.currentTime-(d.seekOffset||10));}],['seekforward',d=>{if(Number.isFinite(el.duration))el.currentTime=Math.min(el.duration,el.currentTime+(d.seekOffset||10));}]]){try{navigator.mediaSession.setActionHandler(a,f);}catch{}}}catch{}}
function mode(asAudio){if(!record)return;const old=activeMedia,time=old.currentTime||0;old.pause();activeMedia=asAudio?audio:video;video.hidden=asAudio;audio.hidden=!asAudio;const src=objectURL||record.url;if(activeMedia.src!==src)activeMedia.src=src;const seek=()=>{try{activeMedia.currentTime=Math.min(time,Number.isFinite(activeMedia.duration)?activeMedia.duration:time);}catch{}};if(activeMedia.readyState>=1)seek();else activeMedia.addEventListener('loadedmetadata',seek,{once:true});const promise=activeMedia.play();promise?.catch(()=>setStatus(tr('loadFirst')));setStatus(asAudio?tr('localAudio'):'');mediaMetadata(activeMedia);}
function loadRecord(r){Q.stop();stopOwn();record=r;owner=r.rank||Q.active?.rank;nativeLabels();$('#nativeTitle').textContent=r.label;objectURL=r.blob?URL.createObjectURL(r.blob):null;video.src=objectURL||r.url;activeMedia=video;video.hidden=r.type==='audio';audio.hidden=r.type!=='audio';if(r.type==='audio'){audio.src=video.src;video.removeAttribute('src');activeMedia=audio;}dock.hidden=false;$('#nativeVideoMode').disabled=r.type==='audio';$('#nativePip').disabled=r.type==='audio';setStatus(tr('rights'));activeMedia.play().catch(()=>setStatus(tr('loadFirst')));}
Q.openNativeRecord=loadRecord;$('#nativeClose').onclick=stopOwn;$('#nativeAudioMode').onclick=()=>mode(true);$('#nativeVideoMode').onclick=()=>mode(false);$('#nativeReturn').onclick=()=>{if(owner)Q.open(owner);};
$('#nativePip').onclick=()=>{if(activeMedia!==video||video.readyState<2){setStatus(tr('loadFirst'));return;}try{if(video.webkitSupportsPresentationMode&&!video.webkitSupportsPresentationMode('picture-in-picture')){setStatus(tr('unsupported'));return;}if(video.requestPictureInPicture){const req=video.requestPictureInPicture();req?.catch(()=>setStatus(tr('unsupported')));}else if(video.webkitSetPresentationMode)video.webkitSetPresentationMode('picture-in-picture');else setStatus(tr('unsupported'));}catch{setStatus(tr('unsupported'));}};
$('#nativeSave').onclick=async()=>{if(!record?.blob)return;try{await Q.idb('put','native-recording:'+owner,record);setStatus(tr('saved'));}catch{setStatus(tr('failed'));}};
for(const el of[video,audio]){el.addEventListener('play',()=>{document.querySelectorAll('audio,video').forEach(other=>{if(other!==el)other.pause();});mediaMetadata(el);});el.addEventListener('error',()=>setStatus(tr('failed')+' '+tr('filesHelp')));}
// Drag only the handle. Native timeline and volume gestures must never move the panel.
let drag=null;const handle=$('#nativeDrag');handle.style.touchAction='none';handle.addEventListener('pointerdown',e=>{if(e.target.closest('button,input')||e.button>0)return;const r=dock.getBoundingClientRect();drag={x:e.clientX-r.x,y:e.clientY-r.y};handle.setPointerCapture(e.pointerId);e.preventDefault();});handle.addEventListener('pointermove',e=>{if(!drag)return;const r=dock.getBoundingClientRect(),x=Math.max(8,Math.min(innerWidth-r.width-8,e.clientX-drag.x)),y=Math.max(8,Math.min(innerHeight-r.height-8,e.clientY-drag.y));Object.assign(dock.style,{left:x+'px',top:y+'px',right:'auto',bottom:'auto'});});handle.addEventListener('pointerup',()=>drag=null);handle.addEventListener('pointercancel',()=>drag=null);
async function fileBox(p){const root=$('#recordingsPanel');if(!root||!p)return;const previous=$('#nativeFileBox');previous?.remove();const box=document.createElement('article');box.id='nativeFileBox';box.className='reading-guide';box.innerHTML=`<h3>${E(tr('newFiles'))}</h3><p>${E(tr('filesHelp'))}</p><label class="btn">${E(tr('choose'))}<input id="passageMediaFile" type="file" accept="video/mp4,audio/*" hidden></label> <button class="btn" id="nativeRestore" hidden>${E(tr('restore'))}</button><p id="fileStatus" role="status"></p>`;root.prepend(box);$('#passageMediaFile').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>250*1048576||!(/^(audio\/|video\/mp4)/.test(f.type)||/\.(mp4|m4a|mp3|wav|ogg)$/i.test(f.name))){$('#fileStatus').textContent=tr('failed');return;}loadRecord({rank:p.rank,label:f.name,type:f.type.startsWith('audio')||/\.(m4a|mp3|wav|ogg)$/i.test(f.name)?'audio':'video',blob:f,bytes:f.size,at:Date.now()});};const saved=await Q.idb('get','native-recording:'+p.rank).catch(()=>null);if(Q.active?.rank!==p.rank||!saved)return;const b=$('#nativeRestore');if(b){b.hidden=false;b.onclick=()=>loadRecord(saved);}}
const oldRecordings=Q.recordings;Q.recordings=async()=>{const p=Q.active;await oldRecordings();if(Q.active===p)fileBox(p);};
window.addEventListener('fq:language',()=>{nativeLabels();if(Q.active)renderGuide();});nativeLabels();Q.render();if(Q.active)renderGuide();
})();
